def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    rects = []

    # Each intended object is a filled rectangle; stray pixels may replace a
    # few cells. Find dense rectangles of every non-background color.
    for color in counts:
        if color == bg:
            continue
        ps = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                ps[r + 1][c + 1] = (ps[r][c + 1] + ps[r + 1][c]
                                    - ps[r][c] + int(grid[r][c] == color))
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        n = (ps[r1 + 1][c1 + 1] - ps[r0][c1 + 1]
                             - ps[r1 + 1][c0] + ps[r0][c0])
                        if n >= 4 and n / area >= 0.80:
                            rects.append((area, color, r0, r1, c0, c1))

    # Background outside detected patches; paint larger rectangles first so
    # smaller inset objects are retained over them.
    out = [[bg] * w for _ in range(h)]
    for area, color, r0, r1, c0, c1 in sorted(rects, reverse=True):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out
