 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    core = [v for v, _ in freq.most_common(3)]
    bg = core[0]

    # Large same-color components identify the actual objects. Dense
    # rectangular components restore any rare-color substitutions inside.
    rect_cells = {}
    for color in core[1:]:
        seen = [[False] * w for _ in range(h)]
        rect_cells[color] = set()
        for r in range(h):
            for c in range(w):
                if seen[r][c] or grid[r][c] != color:
                    continue
                q = deque([(r, c)])
                seen[r][c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and not seen[yy][xx]
                                and grid[yy][xx] == color):
                            seen[yy][xx] = True
                            q.append((yy, xx))
                if len(cells) < 4:
                    continue
                r0 = min(y for y, x in cells)
                r1 = max(y for y, x in cells)
                c0 = min(x for y, x in cells)
                c1 = max(x for y, x in cells)
                area = (r1 - r0 + 1) * (c1 - c0 + 1)
                if len(cells) / area >= 0.78:
                    rect_cells[color].update(
                        (y, x) for y in range(r0, r1 + 1)
                        for x in range(c0, c1 + 1))

    out = [[v if v in core else bg for v in row] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] in core:
                continue
            owners = [color for color, cells in rect_cells.items() if (r, c) in cells]
            if owners:
                out[r][c] = owners[0]
                continue
            around = Counter()
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                y, x = r + dr, c + dc
                if 0 <= y < h and 0 <= x < w and grid[y][x] in core:
                    around[grid[y][x]] += 1
            if around:
                best = max(around.values())
                choices = [color for color, n in around.items() if n == best]
                if bg not in choices and best >= 2:
                    out[r][c] = max(choices, key=lambda color: freq[color])
                else:
                    out[r][c] = bg
    return out
